<?php
if(!isset($pdo,$id))return;
$assets=[];try{$s=$pdo->prepare('SELECT * FROM ordem_patrimonios WHERE ordem_id=? AND ativo=1 ORDER BY consultado_em DESC');$s->execute([(int)$id]);$assets=$s->fetchAll();}catch(Throwable $e){}
?>
<div class="card p-3 mb-4" id="patrimonios-os"><div class="d-flex justify-content-between"><h2 class="h5">Patrimônios vinculados</h2><?php if(has_permission('patrimonio.consultar')):?><a class="btn btn-sm btn-outline-primary" href="<?=e(app_path('patrimonios'))?>">Consulta completa</a><?php endif;?></div><div id="assetOsMessage"></div>
<?php if(has_permission('patrimonio.vincular')):?><div class="input-group mb-3"><input id="assetOsCode" class="form-control" placeholder="Código de barras (USB ou manual)" maxlength="120"><button id="assetOsLink" class="btn btn-primary">Consultar e vincular</button></div><?php endif;?>
<div class="row g-3"><?php foreach($assets as $a):?><div class="col-md-6"><div class="border rounded p-3 h-100"><b><?=e($a['descricao_snapshot']?:$a['numero_patrimonio']?:$a['codigo_barras'])?></b><div class="small">Código: <?=e($a['codigo_barras']?:'-')?> | Patrimônio: <?=e($a['numero_patrimonio']?:'-')?></div><div class="small">Marca/modelo: <?=e(trim($a['marca_snapshot'].' '.$a['modelo_snapshot'])?:'-')?></div><div class="small">Série: <?=e($a['serie_snapshot']?:'-')?> | Local: <?=e($a['localizacao_snapshot']?:'-')?></div><div class="small text-primary">Dados consultados no sistema externo de patrimônio em <?=e($a['consultado_em'])?>.</div><div class="mt-2"><?php if(has_permission('patrimonio.atualizar_snapshot')):?><button class="btn btn-sm btn-outline-secondary asset-refresh" data-id="<?=$a['id']?>">Consultar dados atuais/atualizar</button><?php endif;?> <?php if(has_permission('patrimonio.desvincular')):?><button class="btn btn-sm btn-outline-danger asset-unlink" data-id="<?=$a['id']?>">Desvincular</button><?php endif;?></div></div></div><?php endforeach;?><?php if(!$assets):?><div class="text-muted">Nenhum patrimônio vinculado.</div><?php endif;?></div></div>
<script>(()=>{const api=<?=json_encode(app_path('patrimonio_api'))?>,csrf=<?=json_encode(csrf_token())?>,os=<?=(int)$id?>;async function send(action,data={}){const r=await fetch(api,{method:'POST',cache:'no-store',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({action,csrf,...data})});const j=await r.json();if(!j.ok)throw new Error(j.message);return j}const show=(m,k)=>document.getElementById('assetOsMessage').innerHTML=`<div class="alert alert-${k}">${m}</div>`;document.getElementById('assetOsLink')?.addEventListener('click',async()=>{try{await send('link',{ordem_id:os,type:'codigo',term:document.getElementById('assetOsCode').value});location.reload()}catch(e){show(e.message,'danger')}});document.querySelectorAll('.asset-unlink').forEach(b=>b.onclick=async()=>{if(!confirm('Desvincular este patrimônio?'))return;try{await send('unlink',{id:b.dataset.id});location.reload()}catch(e){show(e.message,'danger')}});document.querySelectorAll('.asset-refresh').forEach(b=>b.onclick=async()=>{try{const current=await send('current',{id:b.dataset.id}),keys=Object.keys(current.differences);if(!keys.length){show('Os dados atuais são iguais ao snapshot.','info');return}if(!confirm('Diferenças: '+keys.join(', ')+'. Atualizar preservando auditoria?'))return;await send('refresh',{id:b.dataset.id});location.reload()}catch(e){show(e.message,'danger')}})})();</script>
